  if (keywordLandingBySlug[slug]?.cluster === "customer-management") return <section className="category-specimen specimen-crm"><div className="specimen-meta"><span>RELATIONSHIP RECORD / 01</span><b>CONTEXT TO FOLLOW-UP</b></div><div className="crm-panel-grid"><article><span>CONTEXT</span><strong>Keep the record useful</strong><p>Start with the customer context people need to understand.</p></article><article><span>OWNER</span><strong>Make the next action clear</strong><p>Keep ownership, timing and relevant context visible where work happens.</p></article><article><span>REVIEW</span><strong>Close the loop</strong><p>Use a real scenario to check that the routine supports a useful outcome.</p></article></div></section>;
