  if (keywordLandingBySlug[slug]?.cluster === "startup-operations") return <section className="category-specimen specimen-startup-stack"><div className="specimen-meta"><span>STARTUP STACK / 01</span><b>FOUNDATION BEFORE SCALE</b></div><div className="startup-stack-grid"><article><span>NOW</span><strong>Choose the current constraint</strong><p>Start where a customer or team outcome is slowing down.</p></article><article><span>DEFAULT</span><strong>Set a lightweight system</strong><p>Make one record, one owner and one review point clear.</p></article><article><span>NEXT</span><strong>Test before scaling</strong><p>Use a live workflow to learn what the next version needs.</p></article></div><div className="startup-foot"><span>Foundation</span><i /><span>Evidence</span><i /><span>Scale</span></div></section>;
