  if (keywordLandingBySlug[slug]?.cluster === "productivity") return <section className="category-specimen specimen-instrument"><div className="specimen-meta"><span>OPERATING ROUTINE / 01</span><b>LIGHTER WORK</b></div><div className="instrument-grid"><article><span>TRIGGER</span><strong>What starts the routine?</strong></article><i /><article><span>OWNER</span><strong>Who takes the next action?</strong></article><i /><article><span>REVIEW</span><strong>What confirms it is complete?</strong></article></div></section>;
  if (keywordLandingBySlug[slug]?.cluster === "marketing") return <section className="category-specimen specimen-workflow"><div className="specimen-meta"><span>AUDIENCE PATH / 01</span><b>USEFUL SIGNAL</b></div><div className="workflow-grid"><article><span>QUESTION</span><strong>Name the audience need.</strong></article><article><span>MESSAGE</span><strong>Make the response useful.</strong></article><article><span>ACTION</span><strong>Clarify the next move.</strong></article></div></section>;
  if (family === "control") return <section className="category-specimen specimen-control"><div className="specimen-meta"><span>REVIEW CONTROL / 01</span><b>AI WORKFLOW</b></div><div className="specimen-control-grid"><article><span>INPUT</span><strong>Is the task bounded?</strong><p>Start with a defined job and suitable context.</p></article><article><span>REVIEW</span><strong>Who checks the output?</strong><p>Keep ownership visible before the work is used.</p></article><article><span>DATA</span><strong>What is being shared?</strong><p>Consider information handling before you connect a service.</p></article></div></section>;
