function reciprocalCategoryLinks(page: KeywordLandingPage) {
  const clusterId = page.cluster ?? legacyClusters[page.slug];
  const cluster = crmClusterSlugs.has(page.slug) ? keywordLandingPages.filter((item) => crmClusterSlugs.has(item.slug)) : clusterId ? keywordLandingPages.filter((item) => (item.cluster ?? legacyClusters[item.slug]) === clusterId) : page.hubPath === "/business-software/" ? keywordLandingPages.filter((item) => item.hubPath === "/business-software/") : [];
  if (cluster.length === 0) return page.related;
  const currentIndex = cluster.findIndex((item) => item.slug === page.slug);
  const offsets = [1, -1, 2, -2, 3, -3];
  const linked = offsets.map((offset) => cluster[(currentIndex + offset + cluster.length) % cluster.length]).filter((item): item is KeywordLandingPage => Boolean(item));
  return Array.from(new Map(linked.map((item) => [item.path, item])).values()).map((item) => ({ title: item.title, path: item.path }));
}

export default function KeywordLandingPage({ slug }: { slug: string }) {
  const page = keywordLandingBySlug[slug];
  if (!page) return <NotFound />;
  const family = specimenFamily(page.slug);
  const pageCluster = page.cluster ?? legacyClusters[page.slug];
  const relatedLinks = reciprocalCategoryLinks(page);
  const isStrategic = page.eyebrow.includes("strategic category guide");
  const isPillarSupport = page.eyebrow.includes("pillar and supporting guide");
  const isExpansion = isStrategic || isPillarSupport;
  const faqItems = page.slug === "business-software-solutions" ? businessSoftwareSolutionsFaqs : page.slug === "crm-software-for-startups" ? crmSoftwareForStartupsFaqs : page.slug === "crm-software-comparison" ? crmSoftwareComparisonFaqs : page.slug === "best-free-crm-software" ? bestFreeCrmSoftwareFaqs : undefined;
  return <div className={`site-shell page-shell keyword-page ${isExpansion ? "keyword-expansion" : ""} ${isStrategic ? "keyword-strategic" : ""} ${isPillarSupport ? "keyword-small-business" : ""} keyword-page-${family} keyword-page-${page.slug} keyword-cluster-${pageCluster ?? "general"}`}><PageMeta title={page.title} path={page.path} description={page.description} faqItems={faqItems} /><SiteHeader /><main id="main-content">
    <section className="keyword-hero"><div className="breadcrumb"><Link href="/">Home</Link><ChevronRight size={14} /><Link href={page.hubPath}>{page.hubLabel}</Link><ChevronRight size={14} /><span>{page.title}</span></div><div className="keyword-hero-grid"><div><div className="page-signal-bar"><span>PRIMARY KEYWORD / {page.keyword.toUpperCase()}</span><i /><span>Practical category guide</span></div><span className="eyebrow"><LayoutPanelTop size={15} /> {page.eyebrow}</span><h1 className={isStrategic ? "strategic-hero-title" : isPillarSupport ? "small-business-hero-title" : undefined}>{page.title}<em>{heroAccent(page)}</em></h1><p>{page.description}</p></div><HeroSignalPanel page={page} cluster={pageCluster} /></div>
    </section>
    <section className="keyword-layout"><aside className="keyword-rail"><span>START HERE</span><Link href={page.hubPath}>Open {page.hubLabel}</Link><Link href="/topic-authority/">Open topic map</Link><a href="#checklist">Use the fit checklist</a><a href="#next">Explore related pages</a></aside><article className={`keyword-body keyword-body-${pageCluster ?? family}`}>{page.slug === "business-software-solutions" && <BusinessSoftwareSolutionsDirectAnswer />}{page.slug === "crm-software-for-startups" && <CrmStartupsDirectAnswer />}{page.slug === "crm-software-comparison" && <CrmComparisonDirectAnswer />}{page.slug === "best-free-crm-software" && <BestFreeCrmDirectAnswer />}<p className="keyword-lede">{page.lead}</p>{page.slug === "business-software-solutions" && <BusinessSoftwareSolutionsAeo />}{page.slug === "crm-software-for-startups" && <CrmStartupsAeo />}{page.slug === "crm-software-comparison" && <CrmComparisonAeo />}{page.slug === "best-free-crm-software" && <BestFreeCrmAeo />}<CategorySpecimen slug={page.slug} /><AuthorityPathway page={page} cluster={pageCluster} /><SoftwareReviewShortlist page={page} /><section className="keyword-decision" aria-label="Decision prompt"><span>DECISION PROMPT / 03</span><h2>{page.decision}</h2><div><i /><p>Use the category as a way to understand the work first. Product details, plan scope and implementation requirements should be confirmed directly with the provider before you commit.</p></div></section><section id="checklist" className="keyword-checklist"><div className="body-label"><span>04</span><b>Fit checklist</b></div><h2>{["comparisons", "high-intent-evaluation"].includes(pageCluster ?? "") ? <>Give every option the <em>same test.</em></> : ["ai", "ai-business-use-cases"].includes(pageCluster ?? "") ? <>Set the task, then protect <em>the review.</em></> : ["marketing", "website-tools", "seo-tools"].includes(pageCluster ?? "") ? <>Build a clearer <em>audience path.</em></> : <>Use the category around <em>the decision.</em></>}</h2><div className="keyword-check-grid">{page.checkpoints.map((item, index) => <article key={item.title}><span>0{index + 1}</span><CheckCircle2 size={18} /><h3>{item.title}</h3><p>{item.detail}</p></article>)}</div></section><section id="next" className="keyword-related"><div className="body-label"><span>05</span><b>{crmClusterSlugs.has(page.slug) ? "CRM network · 06 reciprocal links" : pageCluster ? `${clusterLabels[pageCluster] ?? "Related"} network · reciprocal links` : page.hubPath === "/business-software/" ? "Business Software network · 06 reciprocal links" : "Continue exploring"}</b></div><div>{relatedLinks.map((item) => <Link href={item.path} key={item.path}><span>{item.title}</span><ArrowUpRight size={17} /></Link>)}</div></section></article></section>
  </main><SiteFooter /></div>;
}
